#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNucleo: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Nucleo

    public static func lift(_ handle: UInt64) throws -> Nucleo {
        return Nucleo(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Nucleo) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Nucleo {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Nucleo, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNucleo_lift(_ handle: UInt64) throws -> Nucleo {
    return try FfiConverterTypeNucleo.lift(handle)
}

